insert into public.mailbox_messages (id, direction, status, thread_id, prospect_id, reply_to_id, category, from_email, from_name, to_email, subject, body_text, summary, review_reason, sent_by, received_at, sent_at, is_demo, created_at) values
  ('d0000000-0000-4000-8000-000000020001', 'entrant', 'traite', 'd0000000-0000-4000-8000-000000020001', 'd0000000-0000-4000-8000-0000000a0002', null, 'interesse', 'contact@restaurant-le-petit-carillon.example', 'Claire (fictif)', null, 'Re: Une maquette de site pour Le Petit Carillon', E'Bonjour,\n\nLe style chaleureux me plaît beaucoup. Ça coûterait combien pour le mettre en ligne ?\n\nClaire', 'Préfère le style chaleureux et demande le prix.', null, null, '2026-10-27T08:12:00Z', null, true, '2026-10-27T08:12:00Z'),
  ('d0000000-0000-4000-8000-000000020002', 'sortant', 'a_valider', 'd0000000-0000-4000-8000-000000020001', 'd0000000-0000-4000-8000-0000000a0002', 'd0000000-0000-4000-8000-000000020001', 'interesse', null, null, 'contact@restaurant-le-petit-carillon.example', 'Re: Une maquette de site pour Le Petit Carillon', E'Bonjour,\n\nMerci pour votre retour, ravi que le style chaleureux vous plaise. Deux formules existent : Essentiel à 390 € puis 19 € par mois, ou Pro à 690 € puis 39 € par mois. Pour vous, l''Essentiel suffit largement. Voulez-vous que je vous envoie le détail ?\n\nBien cordialement,\nAmbroise Le Clerc\nDevanture', null, 'artisan intéressé : à toi de conclure · sujet sensible : prix ou tarif', null, null, null, true, '2026-10-27T08:13:00Z'),
  ('d0000000-0000-4000-8000-000000020003', 'entrant', 'traite', 'd0000000-0000-4000-8000-000000020003', 'd0000000-0000-4000-8000-0000000a0003', null, 'question', 'contact@traiteur-saveurs-du-nord.example', null, null, 'Re: Votre maquette', 'Bonjour, je ne trouve pas le lien pour voir la maquette.', 'Ne trouve pas le lien de la maquette.', null, null, '2026-10-26T15:40:00Z', null, true, '2026-10-26T15:40:00Z'),
  ('d0000000-0000-4000-8000-000000020004', 'sortant', 'envoye', 'd0000000-0000-4000-8000-000000020003', 'd0000000-0000-4000-8000-0000000a0003', 'd0000000-0000-4000-8000-000000020003', 'question', null, null, 'contact@traiteur-saveurs-du-nord.example', 'Re: Votre maquette', E'Bonjour,\n\nLe lien est dans mon premier message, juste au-dessus de la question. Il s''ouvre sur ordinateur comme sur téléphone.\n\nBien cordialement,\nAmbroise Le Clerc\nDevanture', null, null, 'agent', null, '2026-10-26T15:42:00Z', true, '2026-10-26T15:41:00Z'),
  ('d0000000-0000-4000-8000-000000020005', 'entrant', 'traite', 'd0000000-0000-4000-8000-000000020005', null, null, 'stop', 'gerant@garage-fictif.example', null, null, 'STOP', 'STOP', 'Demande à ne plus être contacté : ajouté à la liste d''opposition.', null, null, '2026-10-26T10:05:00Z', null, true, '2026-10-26T10:05:00Z');
